INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — Scope limitation when management refuses one specific representation
(1, 'Written Representations', 'During the audit of Graystone Technologies for the year ended December 31, 2025, the CFO signs the management representation letter but refuses to include the representation regarding completeness of contingent liabilities, citing advice from legal counsel. All other representations are provided without qualification. The engagement partner at Hartfield & Associates must evaluate the appropriate response. Under AU-C 580, the auditor should:', '["Evaluate whether the refusal constitutes a scope limitation and consider the effect on the auditor''s report", "Issue a disclaimer of opinion because any refusal to provide representations automatically requires withdrawal", "Accept the remaining representations as sufficient and issue an unmodified opinion", "Obtain oral assurance from the CFO regarding contingent liabilities as a substitute"]'::jsonb, 0, 'Under AU-C 580.20, if management refuses to provide a requested written representation, the auditor must evaluate whether this constitutes a scope limitation and consider the effect on the audit opinion. A refusal does not automatically require a disclaimer — the auditor assesses whether the matter is material and pervasive. Choice B is incorrect because a disclaimer is required only when management refuses all representations, not necessarily a single one.', 'hard', 4),

-- Q2: medium / L3 — Contradictory evidence effect on reliability of all representations
(1, 'Written Representations', 'While auditing Ridgecrest Industries'' December 2025 financial statements, the engagement team at Foxwell & Partners obtains a signed management representation letter stating that all related-party transactions have been disclosed. However, during subsequent substantive testing, the auditor discovers a $340,000 loan to the CEO''s spouse that was not disclosed. The most likely effect of this finding on the auditor''s assessment is that the auditor should:', '["Accept the representation letter as reliable because it was signed before the discovery", "Consider the implications for the reliability of all other management representations", "Withdraw from the engagement immediately without further investigation", "Disregard the representation letter entirely and rely solely on substantive testing"]'::jsonb, 1, 'Under AU-C 580.A23, when contradictory evidence exists regarding a management representation, the auditor must reconsider the reliability of other representations. This discovery raises questions about management''s integrity and the dependability of all assertions in the letter. Choice A is incorrect because the timing of the signature does not validate a representation contradicted by audit evidence — the auditor must evaluate credibility across all representations.', 'medium', 3),

-- Q3: easy / L1 — Definition of written representations
(1, 'Written Representations', 'Under AU-C 580, written representations from management are best described as:', '["Substantive evidence that eliminates the need for further audit testing", "Legal documents that transfer audit liability from the auditor to management", "Written statements provided by management to confirm certain matters and support audit evidence", "Voluntary disclosures that management may choose to provide at its discretion"]'::jsonb, 2, 'Under AU-C 580.03, written representations are written statements by management provided to the auditor to confirm certain matters or support other audit evidence. They are a required form of audit evidence, not optional. Choice A is incorrect because written representations supplement but do not replace substantive audit procedures — they are necessary but not sufficient evidence on their own.', 'easy', 1),

-- Q4: medium / L3 — Oral confirmation cannot substitute for written form
(1, 'Written Representations', 'During the wrap-up of Meridian Healthcare''s 2025 audit, the CEO tells the engagement partner at Langford CPA Group that the company has disclosed all known litigation but refuses to include this statement in the written representation letter, arguing the oral confirmation should suffice. Under AU-C 580, the auditor should conclude that:', '["Oral representations are equally reliable and may substitute for written ones", "Oral representations are acceptable if documented in the audit workpapers", "Documenting the CEO''s verbal assurance in a memo satisfies the requirement", "Written form is required and the oral representation does not fulfill the requirement"]'::jsonb, 3, 'Under AU-C 580.08, written representations must be in written form. Oral statements alone do not satisfy the requirement regardless of how they are documented in the workpapers. The written form provides formality and clarity that oral statements lack. Choice B is incorrect because documenting an oral statement in the workpapers does not transform it into a written representation from management — the representation must come from management in writing.', 'medium', 3),

-- Q5: medium / L2 — Period covered by the representation letter
(1, 'Written Representations', 'Ashby & Caldwell CPA is engaged to audit Silver Lake Enterprises for the year ended December 31, 2025. The audit report will be dated March 12, 2026. The management representation letter should cover:', '["All periods referred to in the auditor''s report", "Only the fiscal year ended December 31, 2025", "The twelve months preceding the date of the auditor''s report", "Only the period from the prior audit report date through December 31, 2025"]'::jsonb, 0, 'Under AU-C 580.15, the written representations cover all periods referred to in the auditor''s report. For a single-year audit this would be the fiscal year, but for comparative statements it covers all years presented. Choice B is incorrect because if comparative financial statements are presented, the representation letter must address all periods covered, not only the current fiscal year.', 'medium', 2),

-- Q6: easy / L1 — Addressee of the management representation letter
(1, 'Written Representations', 'Under AU-C 580, the management representation letter should be addressed to:', '["The entity''s board of directors or audit committee", "The auditor or the audit firm performing the engagement", "The Securities and Exchange Commission", "The entity''s shareholders or investors"]'::jsonb, 1, 'Under AU-C 580.14, the management representation letter is addressed to the auditor. Because the auditor requests and relies on these representations as audit evidence, the letter is directed to the engagement partner or the audit firm. Choice A is incorrect because the board of directors or audit committee may receive a copy but is not the addressee — the letter is a communication from management to the auditor.', 'easy', 1),

-- Q7: hard / L4 — Evaluating representations about opening balances in first-year audit
(1, 'Written Representations', 'Patterson & McCormick CPA is conducting its first audit of Stonebridge Capital Management for the year ended December 31, 2025. The prior-year financial statements were audited by another firm that has since dissolved, and workpapers are unavailable. Management provides a representation letter addressing current-year matters but states it cannot represent the accuracy of opening balances because the prior auditor handled that. The engagement partner should recommend:', '["Accepting management''s position because responsibility for opening balances belonged to the prior auditor", "Issuing a qualified opinion solely because the prior auditor''s workpapers are unavailable", "Declining the engagement because first-year audits require representations from the prior auditor", "Performing additional procedures on opening balances and requiring management to include opening-balance representations"]'::jsonb, 3, 'Under AU-C 580.10, management is responsible for all representations covering the periods in the auditor''s report, including opening balances. The auditor must obtain representations from current management regardless of who audited the prior period. Choice A is incorrect because management cannot delegate responsibility for opening-balance representations to a prior auditor — current management bears responsibility for all financial statement assertions.', 'hard', 4),

-- Q8: easy / L1 — Management acknowledgment of internal control responsibility
(1, 'Written Representations', 'Under AU-C 580, the management representation letter should include an acknowledgment that management is responsible for:', '["Performing all audit procedures necessary to detect material misstatements", "Designing, implementing, and maintaining internal control relevant to the preparation of financial statements", "Approving the audit plan and determining which procedures the auditor will perform", "Ensuring the auditor receives unlimited access to all third-party confirmations"]'::jsonb, 1, 'Under AU-C 580.11, management must acknowledge its responsibility for designing, implementing, and maintaining internal control relevant to the preparation and fair presentation of financial statements. This is a fundamental required representation. Choice A is incorrect because performing audit procedures is the auditor''s responsibility, not management''s — the representation letter confirms management''s distinct governance responsibilities.', 'easy', 1),

-- Q9: medium / L3 — Analyzing qualified completeness representation with hedging language
(1, 'Written Representations', 'During the audit of Eastfield Manufacturing for the year ended December 31, 2025, the CFO signs the representation letter but qualifies the completeness representation by stating ''to the best of our knowledge, subject to ongoing internal review.'' The engagement team at Whittaker & Dean must analyze the impact. The most significant concern this qualification raises is that:', '["The qualification has no effect because all representations are inherently limited to management''s knowledge", "The representation letter is automatically void and the auditor must obtain a new letter", "The auditor should accept the qualification because it demonstrates management''s due diligence", "The qualified language may indicate management is uncertain about the completeness of information provided to the auditor"]'::jsonb, 3, 'Under AU-C 580.A11, the auditor should be alert to qualifications in management''s representations that may indicate uncertainty about the completeness or accuracy of information provided. Adding unexpected qualifiers signals that management may not have fully completed its assessment. Choice A is incorrect because while some representations include standard ''to the best of our knowledge'' language, adding extra qualifiers like ''subject to ongoing review'' departs from the expected format and raises reliability concerns.', 'medium', 3),

-- Q10: easy / L1 — Required representation about accounting policies
(1, 'Written Representations', 'Under AU-C 580, the management representation letter must include a statement that management is responsible for:', '["Selecting and applying accounting policies that conform with the applicable financial reporting framework", "Choosing the audit procedures the auditor will perform", "Determining the audit opinion the auditor will express", "Approving the auditor''s assessment of materiality"]'::jsonb, 0, 'Under AU-C 580.11, management must represent that it is responsible for the selection and application of accounting policies appropriate to the entity''s circumstances, including recognition, measurement, and disclosure. Choice B is incorrect because selecting audit procedures is the auditor''s professional responsibility, not management''s — management has no authority over audit methodology.', 'easy', 1),

-- Q11: medium / L2 — Who signs when CEO has recently resigned
(1, 'Written Representations', 'Greenfield & Associates CPA is completing the audit of Cascade Properties Inc. for the year ended December 31, 2025. The company''s CEO recently resigned, and the board appointed an interim president who has been in the role for only two weeks. The CFO remains in position. The management representation letter should be signed by:', '["Only the CFO, since the interim president lacks sufficient tenure to provide representations", "Only the outgoing CEO, who was in place during the fiscal year under audit", "The interim president and the CFO, as the highest-level members of management currently responsible", "The chair of the board of directors in place of the CEO"]'::jsonb, 2, 'Under AU-C 580.13, the representation letter should be signed by members of management with appropriate responsibilities and knowledge — typically the CEO (or equivalent) and CFO. The interim president serves as the current chief executive and bears responsibility. Choice A is incorrect because excluding the interim president would omit the current chief executive — AU-C 580 requires signatures from the highest-level management currently responsible.', 'medium', 2),

-- Q12: easy / L1 — Required in every audit engagement
(1, 'Written Representations', 'Under AU-C 580, written representations from management are required in:', '["Only audits of publicly traded companies", "Every audit engagement performed under generally accepted auditing standards", "Only audits where the auditor identifies material misstatements", "Only first-year audit engagements"]'::jsonb, 1, 'Under AU-C 580.05, the auditor must request written representations from management in every audit engagement performed under GAAS. This requirement applies regardless of entity size, public or private status, or the nature of findings. Choice A is incorrect because written representations are required for all audits — not only publicly traded companies — as they are a fundamental component of audit evidence.', 'easy', 1),

-- Q13: easy / L1 — Representation about access to information and records
(1, 'Written Representations', 'Under AU-C 580, management''s written representations should include a statement confirming that management has:', '["Provided the auditor with access to all information relevant to the preparation of the financial statements", "Certified that all employees have complied with the entity''s code of conduct", "Verified every transaction recorded during the fiscal year", "Confirmed that internal controls prevented all misstatements"]'::jsonb, 0, 'Under AU-C 580.11, management must represent that it has provided the auditor with all relevant information and access as agreed in the terms of the engagement, including all financial records and related data. Choice B is incorrect because management acknowledges responsibility for fraud prevention and discloses known or suspected fraud — it does not certify universal employee compliance with a code of conduct.', 'easy', 1),

-- Q14: medium / L2 — Uncorrected misstatements representation
(1, 'Written Representations', 'During the audit of Birchwood Financial Services for the year ended December 31, 2025, the engagement team at Kellner & Associates identifies $18,000 in uncorrected misstatements that are individually and in aggregate immaterial. Management agrees the misstatements are immaterial and declines to adjust. The management representation letter should include:', '["No reference to uncorrected misstatements since they are immaterial", "A statement that the auditor accepts responsibility for the uncorrected misstatements", "A summary of corrective actions management will take in the following year", "A statement that management believes the uncorrected misstatements are immaterial to the financial statements as a whole"]'::jsonb, 3, 'Under AU-C 580.11, the representation letter must include a statement that management believes the effects of uncorrected misstatements aggregated by the auditor are immaterial, both individually and in aggregate, to the financial statements as a whole. A summary of the misstatements is typically attached. Choice A is incorrect because even immaterial misstatements must be explicitly acknowledged in the representation letter.', 'medium', 2),

-- Q15: hard / L4 — Going concern representation contradicted by bank denial
(1, 'Written Representations', 'While auditing Northpoint Distribution for the year ended December 31, 2025, the engagement team at Rosewater & Blake identifies significant doubt about going concern. Management provides a representation letter asserting the entity will continue as a going concern based on a projected bank loan renewal. However, the auditor obtains a letter from the bank indicating the loan application was denied on February 20, 2026. The auditor should:', '["Accept management''s representation because the loan denial occurred after year-end", "Treat the bank denial as a non-adjusting subsequent event and disclose it in the notes only", "Consider the contradictory evidence, discuss with management, and evaluate the effect on the going concern assessment and audit opinion", "Issue an unmodified opinion with an emphasis-of-matter paragraph citing management''s representation"]'::jsonb, 2, 'Under AU-C 580.A23 and AU-C 570, when audit evidence contradicts a management representation, the auditor must investigate the discrepancy and reconsider the reliability of representations. The bank denial directly undermines management''s going concern assertion and requires reassessment. Choice A is incorrect because AU-C 580 does not permit the auditor to ignore contradictory evidence — the bank denial calls into question the validity of management''s going concern representation regardless of timing.', 'hard', 4),

-- Q16: medium / L2 — Subsequent events representation covers through report date
(1, 'Written Representations', 'The audit report for Timberline Holdings is dated March 8, 2026. The management representation letter, also dated March 8, 2026, should include a representation that management has disclosed to the auditor all events occurring between December 31, 2025 and:', '["December 31, 2025, the balance sheet date", "February 28, 2026, when fieldwork was substantially completed", "March 8, 2026, the date of the auditor''s report", "March 31, 2026, ninety days after the balance sheet date"]'::jsonb, 2, 'Under AU-C 580.11 and AU-C 560, the representation letter should include management''s acknowledgment of subsequent events through the date of the auditor''s report. Since the letter is dated the same as the report, it covers through that date. Choice B is incorrect because limiting the subsequent events representation to fieldwork completion would leave a gap — the representation must extend through the report date.', 'medium', 2),

-- Q17: easy / L2 — Identifying a typical item in the representation letter
(1, 'Written Representations', 'Bradford & Associates CPA is preparing the representation letter request for its audit of Willow Creek Properties. Which of the following is a matter typically included in the management representation letter?', '["The auditor''s planned sample sizes for substantive testing", "Management''s acknowledgment that it has disclosed all known instances of noncompliance with laws and regulations", "The auditor''s assessment of engagement risk", "A listing of all audit adjustments the auditor plans to propose"]'::jsonb, 1, 'Under AU-C 580.11, the representation letter typically includes management''s acknowledgment of its responsibility for compliance and disclosure of any known noncompliance with laws and regulations that could materially affect the financial statements. Choice A is incorrect because planned sample sizes are part of the auditor''s methodology documented in audit workpapers — they are not included in the management representation letter.', 'easy', 2),

-- Q18: hard / L4 — Representation withdrawn after report issuance
(1, 'Written Representations', 'On March 15, 2026, five days after issuing the audit report for Lakewood Systems, the CFO contacts the engagement partner at Denham & Yorke CPA to withdraw the representation about completeness of related-party disclosures, stating that a previously undisclosed $950,000 transaction with a board member''s company has been identified. The auditor should:', '["Take no action because the report has already been issued", "Notify Lakewood''s audit committee but take no further action regarding the audit opinion", "Evaluate the effect of the undisclosed transaction on the financial statements and consider whether the audit report needs to be revised under AU-C 560", "Reissue the representation letter with the withdrawn representation removed"]'::jsonb, 2, 'Under AU-C 560.14 and AU-C 580, when the auditor becomes aware of facts after the report is issued that may have caused the auditor to revise the report, the auditor must evaluate the matter. The $950,000 undisclosed transaction may represent a material misstatement. Choice A is incorrect because issuance of the report does not relieve the auditor of responsibility — AU-C 560 requires investigation of subsequently discovered facts.', 'hard', 4),

-- Q19: medium / L2 — First-year audit representation covering comparative information
(1, 'Written Representations', 'Elmsford & Associates CPA is conducting its first audit of Pinegrove Tech Solutions for the year ended December 31, 2025. The prior year''s financial statements were unaudited. Comparative information from 2024 is presented alongside the current year. The representation letter should:', '["Include representations covering all periods presented in the financial statements, including comparative information", "Cover only the current year because the prior year was not audited", "Be waived for the first-year engagement because management has no prior audit experience", "Include a representation that the prior auditor approved all prior-year financial statements"]'::jsonb, 0, 'Under AU-C 580.15, the representation letter covers all periods referred to in the auditor''s report. Even in a first-year engagement, if comparative information is presented, management must provide representations about those prior periods. Choice B is incorrect because limiting the letter to only the current year would leave representations incomplete for comparative data included in the financial statements.', 'medium', 2),

-- Q20: medium / L3 — Impact on procedures from vague litigation representation
(1, 'Written Representations', 'During the audit of Coventry Medical Group for the year ended December 31, 2025, management provides a representation letter stating it has disclosed ''all material pending litigation of which management is currently aware.'' The engagement team at Thornbury & Hale notes the hedging language. The auditor should analyze whether the vague phrasing:', '["Is standard representation letter language requiring no further action", "Satisfies AU-C 580 because management cannot represent facts beyond its knowledge", "Should be supplemented with a direct inquiry to the entity''s legal counsel", "Indicates potential undisclosed litigation, warranting expanded inquiry and additional procedures"]'::jsonb, 3, 'Under AU-C 580.A11, the auditor should evaluate qualifications in representations that may signal management uncertainty or incompleteness. Hedging language about litigation disclosure warrants expanded inquiry with management and legal counsel and may require additional procedures. Choice A is incorrect because hedging language deviates from the standard format and suggests management may not have fully identified or disclosed all pending litigation.', 'medium', 3),

-- Q21: easy / L1 — Why written form is specifically required
(1, 'Written Representations', 'The primary reason AU-C 580 requires management representations to be in written form rather than oral is to:', '["Create a legally binding contract between the auditor and management", "Reduce misunderstandings and provide a clear record of the representations made", "Transfer all audit liability from the auditor to management", "Satisfy the requirements of the entity''s board of directors"]'::jsonb, 1, 'Under AU-C 580.08, written representations are required in written form to reduce the possibility of misunderstanding between the auditor and management. The written document provides a clear, formal record of what management has represented. Choice A is incorrect because the representation letter is not a legal contract — it is a form of audit evidence that documents management''s assertions for the auditor''s files.', 'easy', 1),

-- Q22: medium / L2 — Group audit component management representations
(1, 'Written Representations', 'Hammond & Pierce CPA is the group engagement team auditing Redstone Holdings, which has three operating subsidiaries each with its own management team. Under AU-C 580, the group engagement partner should obtain written representations from:', '["Only the management of the parent company, Redstone Holdings", "Only the external auditors of each subsidiary", "The management of each subsidiary but not the parent company", "The management of the parent company and, when necessary, component management of each subsidiary"]'::jsonb, 3, 'Under AU-C 580.13 and AU-C 600, the group engagement partner obtains written representations from parent company management regarding group financial statements. When components are significant, the group auditor may also request representations from component management. Choice A is incorrect because relying solely on parent company representations may not provide sufficient coverage for component-level matters.', 'medium', 2),

-- Q23: medium / L3 — Cannot date auditor report before receiving signed representation letter
(1, 'Written Representations', 'The audit team at Crawford & Bennett has completed all substantive procedures for the audit of Summit Ridge Consulting for the year ended December 31, 2025 and plans to date the report March 10, 2026. The CFO is traveling and states the representation letter cannot be signed until March 14, 2026. The auditor should conclude that:', '["The auditor should not date the report until the representation letter is received because it is a precondition for issuing the report", "The report may be issued on March 10 and the letter obtained on March 14 as a follow-up item", "The report may be issued if the CFO provides a verbal commitment to sign the letter", "The auditor should request an extension from the audit committee to resolve the timing conflict"]'::jsonb, 0, 'Under AU-C 580.09, the representation letter is dated as of the date of the auditor''s report, and the auditor should obtain it before or on the report date. The representation letter is a precondition for the auditor''s report. Choice B is incorrect because issuing the report before receiving the signed representation letter violates AU-C 580 — the auditor cannot finalize the report without this required evidence.', 'medium', 3),

-- Q24: hard / L3 — Attorney letter response vs. management representation about unasserted claims
(1, 'Written Representations', 'During the audit of Claremont Financial Group for the year ended December 31, 2025, the engagement team at Preston & Kirby receives a response from outside counsel that neither confirms nor denies the existence of unasserted claims. Management''s representation letter states there are no unasserted claims requiring disclosure. The auditor should conclude that:', '["Management''s representation supersedes the attorney''s response because management has primary knowledge of claims", "The attorney''s non-response is irrelevant because the auditor already has management''s written representation", "The auditor should evaluate both responses and the attorney''s equivocal answer may warrant additional inquiry about the reliability of management''s assertion", "The auditor must withdraw from the engagement because the responses are inconsistent"]'::jsonb, 2, 'Under AU-C 580.A23 and AU-C 501, the auditor evaluates all evidence, including both the attorney''s response and management''s representations. An equivocal attorney response warrants further investigation to assess whether management''s assertion about unasserted claims is reliable. Choice A is incorrect because management''s representation does not override an inconclusive attorney response — both evidence sources must be considered together.', 'hard', 3),

-- Q25: medium / L3 — Delay in providing representation letter and risk assessment
(1, 'Written Representations', 'Oakwood & Sterling CPA is auditing Brighton Pharmaceuticals for the year ended December 31, 2025. Management has repeatedly postponed providing the representation letter, initially citing scheduling conflicts and then needing more time to review the draft. The report date target is March 15, 2026. The primary implication of this delay is that:', '["The delay is routine and has no effect on the auditor''s risk assessment", "The auditor must immediately issue a disclaimer of opinion due to the delay", "The auditor should proceed with issuing the report using only the evidence already obtained", "The auditor should consider whether the delay raises concerns about management''s integrity and its potential effect on the reliability of audit evidence"]'::jsonb, 3, 'Under AU-C 580.A24, if management delays providing representations, the auditor should consider the reasons and whether they raise concerns about management integrity. Persistent delays may indicate reluctance to commit to certain assertions, affecting the reliability of other audit evidence. Choice B is incorrect because a disclaimer is premature — the auditor should first investigate the reasons and discuss with those charged with governance before concluding on the opinion.', 'medium', 3),

-- Q26: medium / L2 — Representation about title to assets and liens
(1, 'Written Representations', 'Ashbury & Grant CPA is auditing Crestview Real Estate Holdings for the year ended December 31, 2025. Crestview holds $12.4 million in commercial properties. The representation letter should include a statement that:', '["Management has satisfactory title to all assets, and there are no liens or encumbrances not disclosed in the financial statements", "The auditor has independently verified title to all properties", "All properties have been appraised at fair market value during the current year", "The entity''s insurance policies cover the full replacement cost of all properties"]'::jsonb, 0, 'Under AU-C 580.11, the representation letter should include management''s assertion regarding satisfactory title to assets and disclosure of any liens, pledges, or encumbrances. This supports the rights and obligations assertion. Choice B is incorrect because verifying title is an audit procedure performed by the auditor, not a management representation — the letter captures management''s own assertion about asset ownership.', 'medium', 2),

-- Q27: medium / L3 — Representations about estimates do not substitute for testing
(1, 'Written Representations', 'While auditing Paragon Technologies for the year ended December 31, 2025, a staff auditor at Lexington & Hayes suggests that management''s written representation about the reasonableness of the $4.2 million warranty reserve eliminates the need for substantive testing of the estimate. The correct conclusion is that:', '["The staff auditor is correct because management has primary knowledge of warranty claims", "The representation substitutes for testing only if the warranty reserve is immaterial", "Written representations about estimates do not substitute for the auditor''s independent evaluation of the methods, data, and assumptions used", "The representation is sufficient if management provides supporting documentation attached to the letter"]'::jsonb, 2, 'Under AU-C 580.04, written representations complement but do not substitute for other audit procedures. For accounting estimates, AU-C 540 requires the auditor to independently evaluate the methods, data, and assumptions management used. Choice A is incorrect because management''s knowledge does not relieve the auditor of responsibility to independently assess the estimate — the representation is necessary but not sufficient on its own.', 'medium', 3),

-- Q28: hard / L4 — Legal counsel advises against regulatory compliance representations
(1, 'Written Representations', 'The CEO of Riverstone Logistics informs the engagement partner at Vale & Crawford CPA that the company''s legal counsel has advised against including representations about regulatory compliance in the December 2025 representation letter, citing potential self-incrimination concerns in an ongoing regulatory inquiry. All other representations are provided. The engagement partner should recommend:', '["Accepting the refusal because legal privilege overrides the audit representation requirement", "Obtaining representations about regulatory compliance from Riverstone''s legal counsel instead", "Evaluating whether the refusal constitutes a scope limitation, considering the significance of regulatory compliance to the financial statements and the potential effect on the audit opinion", "Issuing the audit report with a disclaimer because legal counsel''s involvement invalidates all representations"]'::jsonb, 2, 'Under AU-C 580.20, if management refuses to provide a requested representation, the auditor must consider the implications. The auditor evaluates whether the refused representation relates to matters material to the financial statements and whether it constitutes a scope limitation. Choice A is incorrect because while legal concerns are understandable, they do not automatically override the auditor''s need for representations — the auditor must assess significance and determine the effect on the report.', 'hard', 4),

-- Q29: medium / L2 — Review engagement vs. audit representation letter requirements
(1, 'Written Representations', 'Sheffield & Morris CPA performs a review engagement for Clearpoint Services under AR-C 90 and a separate audit engagement for Sunvale Corp. under AU-C standards. The representation letter requirements differ between these engagements in that:', '["Written representations are required for both engagements, though the specific content differs based on the engagement type", "Written representations are required for audits under AU-C 580 but are not required for review engagements", "Written representations are required only for review engagements, not audits", "Written representations are optional for both engagement types"]'::jsonb, 0, 'Both AU-C 580 (audits) and AR-C 90 (reviews) require written management representations, though the specific representations differ based on the level of assurance provided. Review representations focus on matters specific to the limited assurance engagement. Choice B is incorrect because AR-C 90.39 explicitly requires written representations in review engagements — they are not exclusive to audit engagements.', 'medium', 2),

-- Q30: easy / L1 — Management responsibility for fair presentation
(1, 'Written Representations', 'Under AU-C 580, a fundamental representation in the management representation letter is management''s acknowledgment that it is responsible for:', '["Issuing the auditor''s report to shareholders", "The fair presentation of the financial statements in accordance with the applicable financial reporting framework", "Determining the scope of the audit engagement", "Selecting the audit firm and setting audit fees"]'::jsonb, 1, 'Under AU-C 580.11, a core required representation is management''s acknowledgment of its responsibility for the preparation and fair presentation of the financial statements in accordance with the applicable financial reporting framework. Choice A is incorrect because issuing the auditor''s report is the auditor''s responsibility, not management''s — management''s responsibility pertains to the financial statements themselves.', 'easy', 1)
;

COMMIT;
